import { readdir, stat } from "node:fs/promises";
import { join } from "node:path";
import { COPIES, type ApiPointer, type Manifest, type Source } from "./manifest.ts";
import { pinnedVersion, type Pins } from "./pins.ts";

/** What `versions.json` records for one source. */
export type SourceRecord = {
  readonly version: string;
  readonly fingerprint: string;
  /** Commits of the Git origins, in the order the source lists them. */
  readonly commits: readonly string[];
};

export type Records = Readonly<Record<string, SourceRecord>>;

/** Generated file paths, relative to the copies folder, with their contents. */
export type Generated = ReadonlyMap<string, string>;

const API_INDEX = "api-index";
const SKIPPED_FOLDERS = new Set(["internal", "node_modules", "dist"]);
const MODULE_FILE = /\.(d\.)?ts$/;
const MAX_SUMMARY = 160;

const copiesPath = (name: string, version: string): string => `${COPIES}/${name}/${version}`;

/** The first sentence of the doc comment that opens a file. */
const summaryOf = (text: string): string => {
  const match = /^(?:\s*\/\/\/.*\n)*\s*\/\*\*([\s\S]*?)\*\//.exec(text);
  if (match?.[1] === undefined) return "";

  const lines = match[1]
    .trim()
    .split("\n")
    .map((line) => line.replace(/^\s*\*?\s?/, "").trim());

  const end = lines.findIndex((line) => line === "" || line.startsWith("@"));
  const paragraph = (end === -1 ? lines : lines.slice(0, end)).join(" ");
  const sentence = /^.*?[.!?](?=\s|$)/.exec(paragraph)?.[0] ?? paragraph;
  return sentence.slice(0, MAX_SUMMARY);
};

const moduleFiles = async (root: string): Promise<string[]> => {
  const found: string[] = [];

  for (const entry of await readdir(root, { recursive: true, withFileTypes: true })) {
    const folder = entry.parentPath.slice(root.length + 1);
    const skipped = folder.split("/").some((part) => SKIPPED_FOLDERS.has(part));

    if (entry.isFile() && MODULE_FILE.test(entry.name) && !skipped)
      found.push(join(folder, entry.name));
  }

  return found.toSorted();
};

const modulePage = async (cwd: string, pointer: ApiPointer): Promise<string> => {
  const root = join(cwd, "node_modules", pointer.path);
  const lines = [`# ${pointer.path}`, ""];

  for (const file of await moduleFiles(root)) {
    const summary = summaryOf(await Bun.file(join(root, file)).text());
    const name = file.replace(MODULE_FILE, "");
    lines.push(summary === "" ? `- \`${name}\`` : `- \`${name}\`: ${summary}`);
  }

  return `${lines.join("\n")}\n`;
};

const pagePath = (source: Source, version: string, pointer: ApiPointer): string =>
  `${source.package}/${version}/${API_INDEX}/${pointer.path.replaceAll("/", "-")}.md`;

const isFolder = async (cwd: string, pointer: ApiPointer): Promise<boolean> =>
  (await stat(join(cwd, "node_modules", pointer.path))).isDirectory();

const docsLines = async (copies: string, source: Source, version: string): Promise<string[]> => {
  const root = join(copies, source.package, version);

  const entries = (await readdir(root, { withFileTypes: true })).filter(
    (entry) => entry.name !== API_INDEX,
  );

  const names = entries.map((entry) => (entry.isDirectory() ? `${entry.name}/` : entry.name));
  const count = await Array.fromAsync(new Bun.Glob("**/*").scan({ cwd: root, onlyFiles: true }));
  const files = count.filter((file) => !file.startsWith(`${API_INDEX}/`)).length;

  const noun = files === 1 ? "file" : "files";

  return [
    `- Docs: \`${copiesPath(source.package, version)}/\` (${files} ${noun}: ${names.join(", ")})`,
  ];
};

const originLines = (source: Source, version: string, record: SourceRecord): string[] => {
  const gitSets = source.docs.flatMap((set) => (set.origin.kind === "git" ? [set.origin] : []));

  return gitSets.map((origin, index) => {
    const ref =
      "tag" in origin.ref
        ? `tag ${origin.ref.tag.replaceAll("{version}", version)}`
        : `branch ${origin.ref.branch}`;

    const note = "branch" in origin.ref ? " (not pinned to the installed version)" : "";
    return `- From: ${origin.repository}, ${ref}, commit ${record.commits[index]?.slice(0, 12) ?? "unknown"}${note}`;
  });
};

/**
 * Builds `index.md` and the module pages it links to. `copies` holds the copied docs; the API
 * folders are read from the installed packages.
 */
export const buildIndex = async (
  cwd: string,
  copies: string,
  manifest: Manifest,
  pins: Pins,
  records: Records,
): Promise<Generated> => {
  const generated = new Map<string, string>();

  const sections = [
    "# Reference index",
    "",
    "Generated by `mise run docs`; do not edit. Read a dependency's entry before writing code against it, and use only APIs found there.",
    "",
    "Docs are copies matched to the pinned version. API files are installed by the package and are read in place.",
  ];

  for (const source of manifest.sources) {
    const version = pinnedVersion(source, pins);
    const record = records[source.package];
    if (version === undefined || record === undefined) continue;

    sections.push("", `## ${source.package} ${version}`, "", source.summary, "");

    sections.push(
      ...(await docsLines(copies, source, version)),
      ...originLines(source, version, record),
    );

    for (const pointer of source.api) {
      const location = `node_modules/${pointer.path}`;

      if (!(await isFolder(cwd, pointer))) {
        sections.push(`- API (${pointer.kind}): \`${location}\``);
        continue;
      }

      const page = pagePath(source, version, pointer);
      generated.set(page, await modulePage(cwd, pointer));
      sections.push(`- API (${pointer.kind}): \`${location}/\`, modules: \`${COPIES}/${page}\``);
    }
  }

  generated.set("index.md", `${sections.join("\n")}\n`);
  return generated;
};
